<div class="admin-shell"><h1 style="font:42px 'Playfair Display',serif">Custom cake requests</h1><nav class="admin-nav"><a href="admin.php">Overview</a><a href="admin-products.php">Products</a><a href="admin-orders.php">Orders</a><a href="admin-settings.php">Settings</a><a href="admin-gallery.php">Gallery</a><a href="admin-notifications.php">Notifications</a><a href="admin-subscribers.php">Newsletter</a><a href="admin-requests.php">Custom requests</a><a href="admin-logout.php">Sign out</a></nav><div class="card-panel table-wrap"><table class="data-table"><thead><tr><th>Request</th><th>Customer</th><th>Preferences</th><th>Description</th><th>Inspiration</th></tr></thead><tbody><?php foreach(array_reverse($items) as $r): ?><tr><td><?= e($r['reference']) ?><br><small><?= e($r['created_at']) ?></small></td><td><?= e($r['name']) ?><br><a href="mailto:<?= e($r['email']) ?>"><?= e($r['email']) ?></a><br><?= e($r['phone']) ?></td><td><?= e($r['occasion']) ?><br><?= e($r['flavour']) ?> · <?= e($r['size']) ?><br>Budget: <?= e($r['budget']) ?><br>Date: <?= e($r['required_date']) ?></td><td><?= e($r['description']) ?><br><small>Colours: <?= e($r['colours']) ?> · Message: <?= e($r['custom_message']) ?></small></td><td><?= !empty($r['image'])?'Stored securely in private/uploads/'.e($r['image']):'No image' ?></td></tr><?php endforeach; ?></tbody></table><?php if(!$items)echo '<p>No requests yet.</p>'; ?></div></div><?php site_footer(); ?>
